#include "string.h"
size_t strlen(const char *рядок_дані) { const char *дані_посада = рядок_дані; while (*дані_посада) дані_посада++; return дані_посада - рядок_дані; }
int memcmp(const void *첫째값, const void *둘째값, size_t 개수) { const unsigned char *координата_X = 첫째값, *세로좌표 = 둘째값; while (개수--) { if (*координата_X != *세로좌표) return (int)*координата_X - *세로좌표; координата_X++; 세로좌표++; } return 0; }
void *memmove(void *місце_дані, const void *рядок_дані, size_t 개수) { unsigned char *координата_X = місце_дані; const unsigned char *세로좌표 = рядок_дані; if (координата_X < 세로좌표) { for (size_t 순번 = 0; 순번 < 개수; 순번++) координата_X[순번] = 세로좌표[순번]; } else { while (개수) { 개수--; координата_X[개수] = 세로좌표[개수]; } } return місце_дані; }
int strncmp(const char *첫째값, const char *둘째값, size_t 개수) { while (개수--) { unsigned char координата_X = *첫째값++, 세로좌표 = *둘째값++; if (координата_X != 세로좌표) return (int)координата_X-세로좌표; if (!координата_X) return 0; } return 0; }
/* lwIP only uses this for small decimal interface numbers. */
long strtol(const char *рядок_дані, char **завершити_виклик_Зміщена_копія, int Фон_значення) {
    const char *ПУСК_Зміщена_копія = рядок_дані; unsigned long значення = 0; int кодування_значення = 1, 하나라도 = 0;
    while (*рядок_дані == ' ' || (*рядок_дані >= 9 && *рядок_дані <= 13)) рядок_дані++;
    if (*рядок_дані == '-' || *рядок_дані == '+') { if (*рядок_дані == '-') кодування_значення = -1; рядок_дані++; }
    if (Фон_значення == 0) Фон_значення = 10;
    while (*рядок_дані >= '0' && *рядок_дані <= '9' && *рядок_дані - '0' < Фон_значення) {
        unsigned цифра_значення = *рядок_дані++ - '0'; 하나라도 = 1;
        if (значення > (0x7ffffffffffffffful - цифра_значення) / (unsigned)Фон_значення) значення = 0x7ffffffffffffffful;
        else значення = значення * Фон_значення + цифра_значення;
    }
    if (завершити_виклик_Зміщена_копія) *завершити_виклик_Зміщена_копія = (char *)(하나라도 ? рядок_дані : ПУСК_Зміщена_копія); return кодування_значення > 0 ? (long)значення : -(long)значення;
}
int atoi(const char *рядок_дані) { return (int)strtol(рядок_дані, 0, 10); }
